// Elige las mejores del día para que Raifel decida qué publicar (nada se publica solo).
const ofertas = $input.first().json.body;
const hoy = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
const fmt = n => '$' + Number(n).toLocaleString('es-AR');
const limite = new Date(hoy); limite.setDate(limite.getDate() - 6);
const frescas = ofertas.filter(o => o.precio_visto >= limite.toISOString().slice(0, 10));
const esNb = o => /notebook|laptop/i.test(o.titulo);
const esCel = o => /celular|smartphone|iphone|galaxy|moto g|redmi/i.test(o.titulo);
const esTv = o => /smart tv|televisor/i.test(o.titulo);
const puntaje = o => (o.descuento_pct || 0) + (o.minimo_historico ? 15 : 0) + (o.relampago ? 5 : 0);
const top = (f, n, hasta) => frescas.filter(o => f(o) && (!hasta || o.precio_actual <= hasta)).sort((a, b) => puntaje(b) - puntaje(a)).slice(0, n);
const bloque = (t, arr) => arr.length ? t + '\n' + arr.map(o => `• ${o.titulo.slice(0, 70)} — ${fmt(o.precio_actual)} (-${o.descuento_pct}%${o.minimo_historico ? ', mínimo histórico' : ''})`).join('\n') : '';
const partes = [bloque('💻 Notebooks (hasta $2 M)', top(esNb, 4, 2000000)), bloque('📱 Celulares', top(esCel, 3)), bloque('📺 Smart TV', top(esTv, 3))].filter(Boolean);
return [{ json: { texto: partes.length ? partes.join('\n\n') : 'Hoy no encontré candidatas frescas.' } }];
